public class SaveWarehouseLayout
{
    public record Command(
        Guid WarehouseId,
        decimal? LayoutWidthM,
        decimal? LayoutHeightM,
        List<ZoneCoordUpdate> Zones,
        List<LocationCoordUpdate> Locations
    ) : ICommand;

    public record ZoneCoordUpdate(Guid Id, decimal? LayoutX, decimal? LayoutY, decimal? LayoutWidth, decimal? LayoutHeight, string? LayoutColor);
    public record LocationCoordUpdate(Guid Id, decimal? CoordX, decimal? CoordY, decimal? CoordZ, decimal? WidthM, decimal? DepthM, decimal? HeightM, short? RotationDeg, string? Aisle, string? RackNo, short? ShelfLevel, short? BinCol);

    public class CommandHandler(IAppDbContext context, ICurrentUser currentUser) : ICommandHandler<Command>
    {
        public async Task HandleAsync(Command command, CancellationToken ct = default)
        {
            // BR-009: validate warehouse dimensions set
            var warehouse = await context.Warehouses
                .FirstOrDefaultAsync(w => w.Id == command.WarehouseId && w.TenantId == currentUser.TenantId, ct)
                ?? throw new NotFoundException(nameof(Warehouse), command.WarehouseId);

            warehouse.LayoutWidthM = command.LayoutWidthM;
            warehouse.LayoutHeightM = command.LayoutHeightM;

            // Batch update zones
            var zoneIds = command.Zones.Select(z => z.Id).ToList();
            var zones = await context.Zones
                .Where(z => zoneIds.Contains(z.Id) && z.TenantId == currentUser.TenantId)
                .ToListAsync(ct);

            foreach (var update in command.Zones)
            {
                var zone = zones.FirstOrDefault(z => z.Id == update.Id);
                if (zone == null) continue;
                // BR-002: zone must fit within warehouse bounds
                if (command.LayoutWidthM.HasValue && update.LayoutX + update.LayoutWidth > command.LayoutWidthM)
                    throw new BusinessException($"Zone {zone.Code} exceeds warehouse width");
                zone.LayoutX = update.LayoutX; zone.LayoutY = update.LayoutY;
                zone.LayoutWidth = update.LayoutWidth; zone.LayoutHeight = update.LayoutHeight;
                zone.LayoutColor = update.LayoutColor;
            }

            // Batch update locations
            var locationIds = command.Locations.Select(l => l.Id).ToList();
            var locations = await context.Locations
                .Where(l => locationIds.Contains(l.Id) && l.TenantId == currentUser.TenantId)
                .ToListAsync(ct);

            foreach (var update in command.Locations)
            {
                var location = locations.FirstOrDefault(l => l.Id == update.Id);
                if (location == null) continue;
                // BR-001: coord bounds
                if (command.LayoutWidthM.HasValue && update.CoordX > command.LayoutWidthM)
                    throw new BusinessException($"Location {location.Code} X coord exceeds warehouse width");
                location.CoordX = update.CoordX; location.CoordY = update.CoordY; location.CoordZ = update.CoordZ;
                location.WidthM = update.WidthM; location.DepthM = update.DepthM; location.HeightM = update.HeightM;
                location.RotationDeg = update.RotationDeg;
                location.Aisle = update.Aisle; location.RackNo = update.RackNo;
                location.ShelfLevel = update.ShelfLevel; location.BinCol = update.BinCol;
            }

            await context.SaveChangesAsync(ct);
        }
    }
}

