public class GetWarehouseInventoryMap
{
    public record Query(Guid WarehouseId, Guid? OwnerId, Guid? ItemId, Guid? LotId) : IQuery<List<LocationOccupancyDto>>;

    public class QueryHandler(IAppDbContext context, ICurrentUser currentUser) : IQueryHandler<Query, List<LocationOccupancyDto>>
    {
        public async Task<List<LocationOccupancyDto>> HandleAsync(Query query, CancellationToken ct = default)
        {
            // Use raw SQL or EF with GroupBy for occupancy calculation
            var result = await context.Locations
                .Where(l => l.WarehouseId == query.WarehouseId
                         && l.TenantId == currentUser.TenantId
                         && l.CoordX != null)
                .Select(l => new LocationOccupancyDto
                {
                    LocationId = l.Id,
                    LocationCode = l.Code,
                    CoordX = l.CoordX!.Value,
                    CoordY = l.CoordY!.Value,
                    WidthM = l.WidthM,
                    DepthM = l.DepthM,
                    RotationDeg = l.RotationDeg ?? 0,
                    CapacityMt = l.CapacityMt,
                    ZoneColor = l.Zone!.LayoutColor ?? "#4A90D9",
                    CurrentQtyMt = l.InventOnHands
                        .Where(oh => (query.OwnerId == null || oh.InventDim!.OwnerId == query.OwnerId)
                                  && (query.ItemId == null || oh.ItemId == query.ItemId)
                                  && (query.LotId == null || oh.InventDim!.LotId == query.LotId))
                        .Sum(oh => oh.QtyMt),
                    OccupancyPct = l.CapacityMt == null || l.CapacityMt == 0 ? null
                        : l.InventOnHands.Sum(oh => oh.QtyMt) / l.CapacityMt * 100
                })
                .ToListAsync(ct);
            return result;
        }
    }
}

