using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Smartlog.Application.Features.WarehouseLayout.Commands;
using Smartlog.Application.Features.WarehouseLayout.Queries;
using Smartlog.Application.Features.WarehouseLayout.Dtos;

namespace Smartlog.Api.Controllers;

[ApiController]
[Route("api/warehouse-layout")]
[Authorize]
public sealed class WarehouseLayoutController(IDispatcher dispatcher) : ControllerBase
{
    [HttpGet("{warehouseId:guid}")]
    public async Task<IActionResult> GetLayout(Guid warehouseId, CancellationToken ct)
    {
        var result = await dispatcher.QueryAsync(new GetWarehouseLayout.Query(warehouseId), ct);
        return Ok(ApiResult<WarehouseLayoutDto>.Success(result));
    }

    [HttpPut("{warehouseId:guid}")]
    public async Task<IActionResult> SaveLayout(Guid warehouseId, [FromBody] SaveWarehouseLayout.Command command, CancellationToken ct)
    {
        await dispatcher.DispatchAsync(command with { WarehouseId = warehouseId }, ct);
        return NoContent();
    }

    [HttpPost("{warehouseId:guid}/floor-plan")]
    [RequestSizeLimit(10 * 1024 * 1024)] // 10MB
    public async Task<IActionResult> UploadFloorPlan(Guid warehouseId, IFormFile file, CancellationToken ct)
    {
        var result = await dispatcher.DispatchAsync(new UploadFloorPlan.Command(warehouseId, file), ct);
        return Ok(ApiResult<UploadFloorPlanResult>.Success(result));
    }

    [HttpGet("{warehouseId:guid}/inventory-map")]
    public async Task<IActionResult> GetInventoryMap(
        Guid warehouseId,
        [FromQuery] Guid? ownerId,
        [FromQuery] Guid? itemId,
        [FromQuery] Guid? lotId,
        CancellationToken ct)
    {
        var result = await dispatcher.QueryAsync(new GetWarehouseInventoryMap.Query(warehouseId, ownerId, itemId, lotId), ct);
        return Ok(ApiResult<List<LocationOccupancyDto>>.Success(result));
    }
}

