import { apiClient } from '@/lib/api-client'
import type { WarehouseLayoutDto, LocationOccupancyDto, SaveLayoutCommand } from './warehouse-layout-schema'

export const warehouseLayoutApi = {
  getLayout: async (warehouseId: string): Promise<WarehouseLayoutDto> => {
    const res = await apiClient.get(`/warehouse-layout/${warehouseId}`)
    return res.data.data
  },

  saveLayout: async (warehouseId: string, data: SaveLayoutCommand): Promise<void> => {
    await apiClient.put(`/warehouse-layout/${warehouseId}`, data)
  },

  uploadFloorPlan: async (warehouseId: string, file: File): Promise<string> => {
    const form = new FormData()
    form.append('file', file)
    const res = await apiClient.post(`/warehouse-layout/${warehouseId}/floor-plan`, form, {
      headers: { 'Content-Type': 'multipart/form-data' },
    })
    return res.data.data.floorPlanUrl as string
  },

  getInventoryMap: async (
    warehouseId: string,
    filters?: { ownerId?: string; itemId?: string; lotId?: string }
  ): Promise<LocationOccupancyDto[]> => {
    const res = await apiClient.get(`/warehouse-layout/${warehouseId}/inventory-map`, { params: filters })
    return res.data.data
  },
}

