import { useState, useCallback } from 'react'
import type { WarehouseLayoutDto, ZoneLayoutDto, LocationLayoutDto } from '../schemas/warehouse-layout-schema'

export interface CanvasConfig {
  canvasWidthPx: number
  warehouseWidthM: number
  warehouseHeightM: number
}

export function useLayoutBuilder(initialData: WarehouseLayoutDto | null) {
  const [zones, setZones] = useState<ZoneLayoutDto[]>(initialData?.zones ?? [])
  const [locations, setLocations] = useState<LocationLayoutDto[]>(initialData?.locations ?? [])
  const [widthM, setWidthM] = useState(initialData?.layoutWidthM ?? null)
  const [heightM, setHeightM] = useState(initialData?.layoutHeightM ?? null)
  const [selectedId, setSelectedId] = useState<string | null>(null)
  const [history, setHistory] = useState<Array<{ zones: ZoneLayoutDto[]; locations: LocationLayoutDto[] }>>([])

  // Meter ↔ pixel conversion
  const meterToPixel = useCallback((meter: number, canvasWidthPx: number) => {
    if (!widthM) return 0
    return (meter / widthM) * canvasWidthPx
  }, [widthM])

  const pixelToMeter = useCallback((pixel: number, canvasWidthPx: number) => {
    if (!widthM) return 0
    return (pixel / canvasWidthPx) * widthM
  }, [widthM])

  const placeZone = useCallback((zoneId: string, dropXPx: number, dropYPx: number, canvasWidthPx: number) => {
    const coordX = pixelToMeter(dropXPx, canvasWidthPx)
    const coordY = pixelToMeter(dropYPx, canvasWidthPx)
    setZones(prev => prev.map(z => z.id === zoneId ? { ...z, layoutX: coordX, layoutY: coordY, layoutWidth: z.layoutWidth ?? 20, layoutHeight: z.layoutHeight ?? 15, isPlaced: true } : z))
  }, [pixelToMeter])

  const placeLocation = useCallback((locationId: string, dropXPx: number, dropYPx: number, canvasWidthPx: number) => {
    const coordX = pixelToMeter(dropXPx, canvasWidthPx)
    const coordY = pixelToMeter(dropYPx, canvasWidthPx)
    setLocations(prev => prev.map(l => l.id === locationId ? { ...l, coordX, coordY, widthM: l.widthM ?? 5, depthM: l.depthM ?? 5, isPlaced: true } : l))
  }, [pixelToMeter])

  const updateZoneCoords = useCallback((zoneId: string, updates: Partial<ZoneLayoutDto>) => {
    setZones(prev => prev.map(z => z.id === zoneId ? { ...z, ...updates } : z))
  }, [])

  const updateLocationCoords = useCallback((locationId: string, updates: Partial<LocationLayoutDto>) => {
    setLocations(prev => prev.map(l => l.id === locationId ? { ...l, ...updates } : l))
  }, [])

  const undo = useCallback(() => {
    if (history.length === 0) return
    const prev = history[history.length - 1]
    setZones(prev.zones)
    setLocations(prev.locations)
    setHistory(h => h.slice(0, -1))
  }, [history])

  return { zones, locations, widthM, heightM, setWidthM, setHeightM, selectedId, setSelectedId, placeZone, placeLocation, updateZoneCoords, updateLocationCoords, meterToPixel, pixelToMeter, undo }
}
